import fitz
import sys

def extract_intro(pdf_path):
    print(f"--- {pdf_path} ---")
    try:
        doc = fitz.open(pdf_path)
        for i in range(min(2, len(doc))):
            print(f"PAGE {i+1}:")
            print(doc[i].get_text())
            print("-" * 40)
        doc.close()
    except Exception as e:
        print(f"Error reading {pdf_path}: {e}")

if __name__ == "__main__":
    for path in sys.argv[1:]:
        extract_intro(path)
